def chain_of_chains(start, end):
    chains = []
    current = start
    while current != end:
        chains.append(current)
        current = next_chains(current)
    return chains

def next_chains(current):
    if current == end:
        return []
    chains = []
    for chain in chains:
        if chain == current:
            return chains + [chain]
        else:
            chains.append(chain)
    return chains

